from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    ordered_names = names if name_order == "ascending" else list(reversed(names))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    rows_by_version = {}
    choices = []
    for name in names:
        rows = {row["version"]: row for row in packages[name]}
        rows_by_version[name] = rows
        allowed = [v for v in rows
                   if v not in blocked.get(name, [])
                   and (name not in pins or v == pins[name])]
        choices.append([None] + allowed)

    best_vector = None
    best = None
    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name) is None or
               not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        edges = {name: [] for name in names if selected[name] is not None}
        valid = True
        for name in edges:
            row = rows_by_version[name][selected[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = selected[target]
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Every installed package must belong to the active closure of roots.
        reached = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            stack.extend(edges.get(name, []))
        if any(selected[name] is not None and name not in reached for name in names):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(child) for child in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue

        vector = tuple(selected[name] if selected[name] is not None else -1
                       for name in ordered_names)
        if (best_vector is None or
                (vector > best_vector if preference == "maximum"
                 else vector < best_vector)):
            best_vector = vector
            best = {name: selected[name] for name in names
                    if selected[name] is not None}

    return {"error": "unsatisfiable"} if best is None else {"versions": best}


def _component_01(data):
    return _dependency_solver(data, "maximum", "ascending")


def _component_02(data):
    return _dependency_solver(data, "minimum", "ascending")


def _component_03(data):
    return _dependency_solver(data, "maximum", "descending")


def _component_04(data):
    return _dependency_solver(data, "minimum", "descending")


def _component_05(data):
    return _dependency_solver(data, "maximum", "ascending")


def _component_06(data):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({job["id"] for job in jobs}):
        return {"error": "impossible"}

    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        feasible = True
        for job in sorted(subset, key=lambda item: (item["start"], item["end"], item["id"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in subset)
        selected_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bits.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    distance = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distance.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            next_mask = mask | bits.get(edge["v"], 0)
            for duration, next_remaining in options:
                next_arrival = depart + duration
                if next_arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if next_arrival < distance.get(next_state, float("inf")):
                    distance[next_state] = next_arrival
                    heapq.heappush(queue, (next_arrival, edge["v"],
                                           next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
